mapper.select:
SELECT id, account_id, fingerprint_sha256, serial_number, subject_dn, not_before, not_after,
       status, version, updated_at
FROM auth_x509_credential

    id = #{id}
    AND account_id = #{accountId}
    AND fingerprint_sha256 = #{fingerprintSha256}

        AND status = 'ACTIVE' AND not_before <= #{validAt} AND not_after > #{validAt}


ORDER BY created_at DESC, id DESC
LIMIT #{limit}

mapper.update:
UPDATE auth_x509_credential

    status = #{status.value},

        revoked_at = #{revokedAt.value},
        revoked_at = NULL,

    version = version + 1

WHERE account_id = #{accountId} AND status = #{expectedStatus}
AND id = #{id}
AND version = #{expectedVersion}
